import{_ as n,o as a,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"Linux高并发系统参数优化","description":"","frontmatter":{"title":"Linux高并发系统参数优化","date":"2016-11-27 18:16","comments":true,"archives":2016,"tags":["linux"]},"headers":[],"relativePath":"posts/2016-11-27-linux-tune-guide/index.md","filePath":"posts/2016/2016-11-27-Linux-tune-guide.md"}'),p={name:"posts/2016-11-27-linux-tune-guide/index.md"};function i(t,s,c,r,o,d){return a(),e("div",null,[...s[0]||(s[0]=[l(`<p>终于毕业证书到手，学生生涯也算是划上完美的句号了。不过工作强度还真的有点大，还经常加班。感觉自己懒散了许多，人果然是生于忧患，死于安乐。。。最近的项目里对业务处理的高并发要求比较高，因此也学习了相关的如何调整 Linux 内核参数让服务器可以处理非常高并发的业务。所以在博客上记录下相关的经验，以供参考。 修改的参数主要是 Linux 系统参数和网络协议栈参数。注意，以下命令都需要在 root 环境下运行。</p><h2 id="linux-操作系统参数" tabindex="-1">Linux 操作系统参数 <a class="header-anchor" href="#linux-操作系统参数" aria-label="Permalink to &quot;Linux 操作系统参数&quot;">​</a></h2><p>系统全局允许分配的最大文件句柄数:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># sysctl -w fs.file-max=2097152</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w fs.nr_open=2097152</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>允许当前会话/进程打开文件句柄数:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># ulimit -n 1048576</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>但是以上命令只是临时修改，重启系统便会失效，所以我们需要持久化这些参数。</p><p>持久化<code>fs.file-max</code>设置到/etc/sysctl.conf 文件:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">fs.file-max</span><span style="color:#032F62;"> =</span><span style="color:#005CC5;"> 1048576</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>/etc/security/limits.conf 持久化设置允许用户/进程打开文件句柄数:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>*      soft   nofile      1048576</span></span>
<span class="line"><span>*      hard   nofile      1048576</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="tcp-协议栈网络参数" tabindex="-1">TCP 协议栈网络参数 <a class="header-anchor" href="#tcp-协议栈网络参数" aria-label="Permalink to &quot;TCP 协议栈网络参数&quot;">​</a></h2><p>并发连接 backlog（定义了网络连接的队列的最大长度）设置:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># sysctl -w net.core.somaxconn=32768</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.ipv4.tcp_max_syn_backlog=16384</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.core.netdev_max_backlog=16384</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>可用知名端口范围:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># sysctl -w net.ipv4.ip_local_port_range=&#39;1000 65535&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>TCP Socket 读写 Buffer 设置:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># sysctl -w net.core.rmem_default=262144</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.core.wmem_default=262144</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.core.rmem_max=16777216</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.core.wmem_max=16777216</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.core.optmem_max=16777216</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.ipv4.tcp_rmem=&#39;1024 4096 16777216&#39;</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.ipv4.tcp_wmem=&#39;1024 4096 16777216&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>TCP 连接追踪设置:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># sysctl -w net.nf_conntrack_max=1000000</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.netfilter.nf_conntrack_max=1000000</span></span>
<span class="line"><span style="color:#6A737D;"># sysctl -w net.netfilter.nf_conntrack_tcp_timeout_time_wait=30</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>TIME-WAIT Socket 最大数量、回收与重用设置:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># net.ipv4.tcp_max_tw_buckets=1048576</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>FIN-WAIT-2 Socket 超时设置:</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;"># net.ipv4.tcp_fin_timeout = 15</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="http://emqtt.com/docs/v2/tune.html" target="_blank" rel="noreferrer">测试调优</a></p>`,26)])])}const m=n(p,[["render",i]]);export{u as __pageData,m as default};
